/* Browser-local manual capture. No platform calls or network requests. */
const trackedBrands=[{name:'ACE Studio',aliases:['ACE Studio','ACEStudio','ACE スタジオ']},{name:'Suno',aliases:['Suno']},{name:'Udio',aliases:['Udio']},{name:'Synthesizer V',aliases:['Synthesizer V Studio','Synthesizer V','Synth V','SynthV']},{name:'Kits AI',aliases:['Kits.ai','Kits AI','Kits.AI']}];
let manualDialog=document.createElement('dialog');manualDialog.id='manualEntry';document.body.appendChild(manualDialog);
function openManual(){manualDialog.innerHTML=`<div class="row dialog-toolbar"><h2>手工录入一次真实测试</h2><button id="cancelManual" type="button">关闭 ×</button></div><div class="dialog-scroll"><p>在平台新建对话，测试一个问题，再粘贴回答。本表不会调用 AI。品牌统计建议可编辑；保存前请核对原文。</p><form id="manualForm"><div class="form"><label>平台 <select id="mp"><option>ChatGPT</option><option>Perplexity</option><option>Gemini</option></select></label><label>模型 <input id="mm" value="网页端未展示" required></label><label>渠道 <select id="ms"><option value="web">网页端</option><option value="api">API</option></select></label><label>目标市场 <select id="mr"><option value="US">美国</option><option value="JP">日本</option><option value="CN">中国</option><option value="LATAM">拉美</option></select></label><label>语言 <select id="ml"><option value="en">英文</option><option value="ja">日文</option><option value="zh">中文</option><option value="es">西语</option></select></label><label>主题 <input id="mt" value="AI singing" required></label><label>题型 <select id="mk"><option value="unbranded">未点名品牌</option><option value="branded">品牌诊断</option></select></label><label>联网搜索 <select id="msearch"><option value="unknown">不确定</option><option value="true">已启用</option><option value="false">未启用</option></select></label><label>测试时间 <input id="mtime" type="datetime-local" required></label></div><label>实际测试问题<textarea id="mq" style="width:100%;min-height:70px" required></textarea></label><label>完整原始回答<textarea id="ma" style="width:100%;min-height:150px" required></textarea></label><button type="button" id="suggestBrands" style="margin:12px 0">从回答预填品牌次数（需要核对）</button><div class="sub">次数是正文中的实际提及次数；位置是该品牌第一次出现时的品牌顺序。未提及填 0，位置不清楚留空。预填不会推断位置。</div><table><thead><tr><th>监测品牌</th><th>提及次数</th><th>首次位置</th></tr></thead><tbody>${trackedBrands.map((b,i)=>`<tr><td>${esc(b.name)}</td><td><input type="number" min="0" step="1" value="0" id="bc${i}" style="width:90px"></td><td><input type="number" min="1" step="1" id="bp${i}" style="width:90px"></td></tr>`).join('')}</tbody></table><label>其他品牌（可选，每行：品牌名 | 次数 | 首次位置）<textarea id="mextra" style="width:100%" placeholder="例如：VOCALOID | 1 | 3"></textarea></label><label>ACE 明确推荐榜单排名（无榜单留空） <input id="mrank" type="number" min="1" step="1"></label><div class="form"><label>引用采集 <select id="mcol"><option value="collected">已检查平台引用来源</option><option value="unknown">未采集／无法获取</option></select></label></div><label>平台引用来源 URL（每行一个；已检查但没有引用时留空）<textarea id="mc" style="width:100%" placeholder="https://example.org/source"></textarea></label><p>仅保存平台显示的来源引用；正文提到的普通链接不自动算作引用。页面标题和截图可另行留存。</p><label><input id="mreview" type="checkbox" required> 我已核对品牌次数、位置和引用，不把预填建议当作最终结果</label><div style="margin-top:20px"><button class="primary">保存到真实数据</button></div></form></div>`;
$('#mtime').value=new Date(Date.now()+8*3600000).toISOString().slice(0,16);$('#cancelManual').onclick=()=>manualDialog.close();$('#mr').onchange=()=>$('#ml').value={US:'en',JP:'ja',CN:'zh',LATAM:'es'}[$('#mr').value];$('#suggestBrands').onclick=()=>{let txt=$('#ma').value;trackedBrands.forEach((b,i)=>{let patterns=b.aliases.slice().sort((a,b)=>b.length-a.length).map(a=>a.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));let re=new RegExp('(?<![A-Za-z0-9])(?:'+patterns.join('|')+')(?![A-Za-z0-9])','gi');$('#bc'+i).value=[...txt.matchAll(re)].length})};
$('#manualForm').onsubmit=e=>{e.preventDefault();try{let brands=trackedBrands.map((b,i)=>({name:b.name,mentions:Number($('#bc'+i).value),first_position:$('#bp'+i).value?Number($('#bp'+i).value):null})).filter(b=>b.mentions>0);for(let line of $('#mextra').value.split('\n').filter(x=>x.trim())){let [name,count,pos]=line.split('|').map(x=>x.trim());brands.push({name,mentions:Number(count),first_position:pos?Number(pos):null})}let citations=$('#mcol').value==='unknown'?null:$('#mc').value.split('\n').filter(x=>x.trim()).map(url=>({url:url.trim(),category:official({url:url.trim()})?'Official':'Unclassified'}));let r={id:'manual-'+Date.now(),tested_at:$('#mtime').value+':00+08:00',platform:$('#mp').value,model:$('#mm').value.trim(),surface:$('#ms').value,target_market:$('#mr').value,region:'unknown',language:$('#ml').value,topic:$('#mt').value.trim(),prompt:$('#mq').value.trim(),prompt_type:$('#mk').value,status:'success',answer:$('#ma').value,brands,citations,ace_recommendation_rank:$('#mrank').value?Number($('#mrank').value):null,search_enabled:$('#msearch').value==='unknown'?null:$('#msearch').value==='true',human_reviewed:true,dictionary_version:'pilot-2026-10-10'};validate([r]);let next=[...real,r];localStorage.setItem(key,JSON.stringify({results:next,prompts}));real=next;demo=false;view='results';topics();render();manualDialog.close();alert('已保存真实测试记录。')}catch(err){alert('未保存：'+err.message)}};manualDialog.showModal()}
const manualButton=document.createElement('button');manualButton.textContent='手工录入';manualButton.id='manualButton';manualButton.onclick=openManual;$('#import').before(manualButton);
